------------ define ------------
local ShowType = {
    NotShowTotal = 0,
    ShowTarget = 1,
    NotShowTarget = 2,
    ShowPre = 3,
}
------------ define ------------

--- from: Assets/BundleResources/Prefabs/UIBattling/Root_TrainingTarget.prefab > name: TargetInfoCell
---@class UIBattlingTrainingTargetNode
---@field Env                           	UIBattlingTrainingTargetNode            
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field TxtProgress2                  	UnityEngine.RectTransform
---@field Mark                          	UnityEngine.RectTransform
---@field CompletedMark                 	UnityEngine.RectTransform
---@field FinishAnimNode                	UnityEngine.RectTransform
---@field Txt_TargetProcess             	TMPro.TextMeshProUGUI
---@field Txt_TargetDes                 	UnityEngine.UI.Text
local UIBattlingTrainingTargetNode = Class('UIBattlingTrainingTargetNode')

------------ LifeCycle ------------
function UIBattlingTrainingTargetNode:__init()
   self:CleanField()
end

function UIBattlingTrainingTargetNode:__delete()
    self:CleanField()
end

function UIBattlingTrainingTargetNode:CleanField()
    self.numTarget = nil
    self.taskId = nil
    self.taskState = nil
    self.stTargetDesc = nil
    self.showType = nil
end

function UIBattlingTrainingTargetNode:Awake()
    self.stTargetDesc = KTool.GetComponent(self.Txt_TargetDes.gameObject, typeof(UISwitchText))
end

function UIBattlingTrainingTargetNode:Start()
end

function UIBattlingTrainingTargetNode:OnDestroy()
    self:CleanCoShowFinish()
    if self.eventBattleOver then
        Events.RemoveListener(Constants.EventNames.BattleGameOverShow, self.eventBattleOver)
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end
