------------ Function ------------

function UIBattlingTrainingTargetNode:GetTypeId()
    return self.taskId
end

---InitData
---初始化 node 信息
---@param data table @ {taskId, desc, value}
function UIBattlingTrainingTargetNode:InitData(data)
    xTry(function()
        self.showType = data.showType
        self.taskId = checkNumber(data.id) -- 任务条件ID
        self.numTarget = checkNumber(data.process) < 1 and checkNumber(data.process) * 100 or checkNumber(data.process) -- 任务目标值
        KTool.SetActive(self.Txt_TargetProcess.gameObject, self.numTarget > 0)
        self.Txt_TargetProcess.text = self:GetTaskProcessDesc(0)
        --checkString(0) .. "/" .. checkString(checkInt(self.numTarget))
        local desc = data.desc -- 任务描述
        if desc then
            self:SetMissionDesc(desc)
        end
        self.stTargetDesc.Status = 1
        self.stTargetDesc:Reset()
        self.taskState = Constants.CombatLevelTaskState.Doing
       
    end)
end

---SetMissionDesc
---任务描述
---@param strValue string 任务描述
function UIBattlingTrainingTargetNode:SetMissionDesc(strValue)
    if self.Txt_TargetDes and self.Txt_TargetDes.text then
        self.Txt_TargetDes.text = checkString(strValue)
    end
end

function UIBattlingTrainingTargetNode:GetTaskProcessDesc(valueNow)
    local desc
    if self.showType == ShowType.ShowTarget then
        desc = checkString(checkInt(valueNow)) .. "/" .. checkString(checkInt(self.numTarget))
    elseif self.showType == ShowType.ShowPre then
        local preValue = checkInt((valueNow / self.numTarget) * 100)
        preValue = preValue >= 100 and 100 or preValue
        desc = checkString(string.format("%d%%",  preValue))
    end
    return desc
end

---SetMissionProcess
---设置任务进度
---@param valueNow number 当前进度
function UIBattlingTrainingTargetNode:SetMissionProcess(valueNow, state)
    xTry(function()
        if self.Txt_TargetProcess and self.Txt_TargetProcess.text then
            if valueNow and self.numTarget then
                self.Txt_TargetProcess.text = self:GetTaskProcessDesc(valueNow)
                --checkString(checkInt(valueNow)) .. "/" .. checkString(checkInt(self.numTarget))
                if state == Constants.BattleConditionState.Succeed then
                    self.taskState = Constants.CombatLevelTaskState.Finished
                    self:SetNodeStateSuccess()
                elseif state == Constants.BattleConditionState.Fail then
                    KTool.SetActive(self.TxtProgress2.gameObject, true)
                    KTool.SetActive(self.Txt_TargetProcess.gameObject, false)
                    self.stTargetDesc.Status = 3
                end
            end
        end
        return valueNow >= self.numTarget
    end)
end

---SetNodeStateSuccess
---设置任务节点 成功
function UIBattlingTrainingTargetNode:SetNodeStateSuccess()
    self:CleanCoShowFinish()
    self.coShowFinish = cs_coroutine.start(function()
        KTool.SetActive(self.FinishAnimNode.gameObject, true)
        self.stTargetDesc.Status = 2
        --self.stTargetDesc:Reset()
        cs_coroutine.yield_return(CS.Engine.Lib.Yielders.GetWaitForSeconds(1.3))
        KTool.SetActive(self.Txt_TargetProcess.gameObject, false)
        KTool.SetActive(self.CompletedMark.gameObject, true)
    end)
end

function UIBattlingTrainingTargetNode:CleanCoShowFinish()
    if self.coShowFinish then
        cs_coroutine.stop(self.coShowFinish)
        self.coShowFinish = nil
    end
end


